FOE = [   # 新兵种首帧（Veo 用），照第二章 jobs_ch2_foe.json
  ('foe_hebei', '河北兵：袁绍军的普通步兵，年轻，土黄色布甲和土黄色头巾，手持长枪，腰挂短刀', '右手握长枪竖在身侧，左手握拳。'),
  ('foe_daji', '河北大戟士：袁绍军精锐头目，高大壮实，土黄色加暗铁色的重铠（几块光滑大甲片），头戴土黄色铁盔，双手持一柄长柄大戟（长杆顶端一个月牙形侧刃加一支直矛尖）', '双手在身前斜握大戟。'),
  ('foe_xiandeng', '先登死士：袁绍军的敢死先锋，精瘦凶悍，头缠红色布条，上身穿土黄色短打外罩一件轻皮甲，手持一面小圆盾和一把短刀，神情决绝', '右手握短刀，左手持小圆盾。'),
]
def pt(id_, kind, who, look, hands):
    return {'id': id_, 'ref': 'pt_sunjian.png' if kind == 'wu' else 'pt_luzhi.png', 'prompt': PT_HEAD.format(who=who, look=look, hands=hands) + PT_TAIL}
jobs = [pt(*x) for x in PT] + [{'id': i, 'ref': 'pt_sunjian.png', 'prompt': PT_HEAD.format(who=w, look='照上面的描述，衣服颜色以土黄色为主，和曹军蓝灰色分得开。', hands=h) + PT_TAIL} for i, w, h in FOE]
(H / 'jobs_ch3_pt.json').write_text(json.dumps(jobs, ensure_ascii=False, indent=1), encoding='utf-8'); print(len(jobs), 'jobs_ch3_pt.json')
